const BASE_URL = "http://127.0.0.1:8000";

export async function getAreas() {
  const response = await fetch(`${BASE_URL}/areas`);
  if (!response.ok) throw new Error("Failed to fetch areas");
  return await response.json();
}

export async function predictTraffic(data) {
  const response = await fetch(`${BASE_URL}/predict`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify(data),
  });

  if (!response.ok) throw new Error("Prediction failed");
  return await response.json();
}

export async function getSignal(data) {
  const response = await fetch(`${BASE_URL}/signal`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify(data),
  });

  if (!response.ok) throw new Error("Signal API failed");
  return await response.json();
}
